def compute_model_placement(gpu_num, models):
    """
    Greedy KVPR-minimizing placement tried over several model orderings;
    keep the placement with the lowest resulting max KVPR.
    Ordering: sort by req_rate/slo descending, assign each model to the
    fitting GPU with the lowest current KVPR (load / free memory).
    """

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free_mem = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
